/* ===== Fresh numericals and Section-II passages (new numbers every time) ===== */
window.GEN = (() => {
  const r2 = (x, d = 2) => Math.round(x * 10 ** d) / 10 ** d;
  const nf = (x, d = 2) => (+x.toFixed(d)).toLocaleString('en-IN', { maximumFractionDigits: d });
  let seq = 0;
  /* numerical answer with tolerance: rel (fraction) or abs */
  function nat(o) {
    const v = o.v, tol = Math.max(Math.abs(v) * (o.rel == null ? 0.01 : o.rel), o.abs || 0);
    return Object.assign({ id: 'G-' + o.g + '-' + (++seq) + '-' + Date.now().toString(36), src: 'G', type: 'nat', lo: r2(v - tol, 4), hi: r2(v + tol, 4), show: nf(v, o.d == null ? 2 : o.d) + (o.unit ? ' ' + o.unit : ''), noRecord: true }, o);
  }
  function mcq(o) { const p = shuffle(o.opts.map((t, i) => [t, i])); return Object.assign({ id: 'G-' + o.g + '-' + (++seq) + '-' + Date.now().toString(36), src: 'G', type: o.type || 'mcq', noRecord: true }, o, { opts: p.map(x => x[0]), ans: (o.ans || [0]).map(a => p.findIndex(x => x[1] === a)) }); }
  const DF = (r, t) => 1 / (1 + r / 100) ** t;
  const MODES = { organic: [2.4, 1.05, 0.38], semidetached: [3.0, 1.12, 0.35], embedded: [3.6, 1.20, 0.32] };
  const W = { EI: 4, EO: 5, EQ: 4, ILF: 10, EIF: 7 };

  /* ---------- small random networks for CPM */
  function network(n) {
    const names = 'ABCDEFGHIJ'.split('').slice(0, n), acts = [];
    names.forEach((nm, i) => { const pre = []; if (i > 0) { const k = i < 2 ? 0 : rnd(1, Math.min(2, i)); const pool = shuffle(names.slice(0, i)); for (let j = 0; j < k; j++) pre.push(pool[j]); } acts.push({ id: nm, d: rnd(2, 9), pre: pre.sort() }); });
    return cpm(acts);
  }
  function cpm(acts) {
    const by = {}; acts.forEach(a => by[a.id] = a);
    acts.forEach(a => { a.es = 0; a.pre.forEach(p => a.es = Math.max(a.es, by[p].ef)); a.ef = a.es + a.d; });
    const T = Math.max(...acts.map(a => a.ef));
    acts.slice().reverse().forEach(a => { const succ = acts.filter(s => s.pre.includes(a.id)); a.lf = succ.length ? Math.min(...succ.map(s => s.ls)) : T; a.ls = a.lf - a.d; a.fl = a.ls - a.es; });
    // all critical paths (start nodes with no pre)
    const paths = []; const walk = (a, path) => { const succ = acts.filter(s => s.pre.includes(a.id) && s.fl === 0 && s.es === a.ef); if (!succ.length) { if (a.ef === T) paths.push(path.concat(a.id)); return; } succ.forEach(s => walk(s, path.concat(a.id))); };
    acts.filter(a => !a.pre.length && a.fl === 0 && a.es === 0).forEach(a => walk(a, []));
    const ends = acts.filter(a => !acts.some(s => s.pre.includes(a.id))), all = []; const walk2 = (a, path, len) => { const succ = acts.filter(s => s.pre.includes(a.id)); if (!succ.length) { all.push([path.concat(a.id), len + a.d]); return; } succ.forEach(s => walk2(s, path.concat(a.id), len + a.d)); }; acts.filter(a => !a.pre.length).forEach(a => walk2(a, [], 0));
    return { acts, T, paths, all, ends };
  }
  const netTable = net => `<div class="tblwrap"><table class="mini"><tr><th>Activity</th><th class="num">Duration (weeks)</th><th>Immediate predecessors</th></tr>${net.acts.map(a => `<tr><td>${a.id}</td><td class="num">${a.d}</td><td>${a.pre.join(', ') || '–'}</td></tr>`).join('')}</table></div>`;
  const netWork = net => `<div class="tblwrap"><table class="mini"><tr><th>Act.</th><th class="num">d</th><th class="num">ES</th><th class="num">EF</th><th class="num">LS</th><th class="num">LF</th><th class="num">Float</th></tr>${net.acts.map(a => `<tr${a.fl === 0 ? ' style="color:var(--ch-i);font-weight:700"' : ''}><td>${a.id}</td><td class="num">${a.d}</td><td class="num">${a.es}</td><td class="num">${a.ef}</td><td class="num">${a.ls}</td><td class="num">${a.lf}</td><td class="num">${a.fl}</td></tr>`).join('')}</table></div>`;

  /* ---------- generators: each returns one question */
  const G = {
    'roi': () => { const inv = pick([100, 120, 150, 200, 250, 500, 800, 1000]) * 1000, n = rnd(4, 6); let cf, net; do { cf = Array.from({ length: n }, () => Math.round(inv * (0.18 + Math.random() * 0.3) / 1000) * 1000); net = cf.reduce((a, b) => a + b, 0) - inv; } while (net <= 0); const v = net / n / inv * 100;
      return nat({ g: 'roi', wk: 3, topic: 't-cba', v, rel: 0.01, abs: 0.05, unit: '%', d: 2, text: `A project needs an initial investment of Rs. ${nf(inv, 0)} (year 0). Its net cash inflows in years 1 to ${n} are Rs. ${cf.map(x => nf(x, 0)).join(', ')}. What is the return on investment (ROI) in percent?`, exp: `Net profit = ${cf.map(x => nf(x, 0)).join(' + ')} − ${nf(inv, 0)} = Rs. ${nf(net, 0)}. Average annual profit = ${nf(net, 0)}/${n} = ${nf(net / n, 0)}. ROI = average annual profit / total investment × 100 = <b>${nf(v)} %</b>.`, trap: [[net / inv * 100, 'used total profit instead of average annual profit'], [(net + inv) / n / inv * 100, 'forgot to subtract the investment from the inflows']] }); },
    'npv': () => { const r = pick([5, 8, 10, 12, 15]), inv = pick([50, 80, 100, 120, 150]) * 1000, n = rnd(3, 5); const cf = Array.from({ length: n }, () => Math.round(inv * (0.18 + Math.random() * 0.3) / 1000) * 1000); const dfs = cf.map((_, t) => DF(r, t + 1)); const v = -inv + cf.reduce((s, c, t) => s + c * dfs[t], 0);
      return nat({ g: 'npv', wk: 3, topic: 't-cba', v, rel: 0, abs: Math.max(120, inv * 0.004), unit: 'Rs.', d: 0, text: `Investment Rs. ${nf(inv, 0)} at year 0; cash inflows Rs. ${cf.map(x => nf(x, 0)).join(', ')} at the end of years 1-${n}. Using a discount rate of ${r} %, what is the net present value (NPV)? (Discount factor = 1/(1+r)<sup>t</sup>.)`, exp: `Discount factors at ${r} %: ${dfs.map(d => d.toFixed(4)).join(', ')}. Discounted inflows: ${cf.map((c, t) => nf(c * dfs[t], 0)).join(' + ')} = ${nf(v + inv, 0)}. NPV = ${nf(v + inv, 0)} − ${nf(inv, 0)} = <b>Rs. ${nf(v, 0)}</b>. Small differences from the 4-digit table are accepted.`, trap: [[cf.reduce((a, b) => a + b, 0) - inv, 'forgot to discount (that is plain net profit)']] }); },
    'payback': () => { const inv = pick([60, 80, 100, 150]) * 1000; let cf, cum, yr; do { cf = Array.from({ length: 6 }, () => Math.round(inv * (0.1 + Math.random() * 0.35) / 1000) * 1000); cum = -inv; yr = 0; for (let i = 0; i < 6; i++) { cum += cf[i]; if (cum >= 0) { yr = i + 1; break; } } } while (!yr || yr < 2);
      let acc = -inv; const rows = cf.map((c, i) => { acc += c; return `Y${i + 1}: ${nf(acc, 0)}`; });
      return nat({ g: 'payback', wk: 3, topic: 't-cba', v: yr, rel: 0, abs: 0.01, unit: 'year', d: 0, text: `Investment Rs. ${nf(inv, 0)} at year 0; net inflows in years 1-6: Rs. ${cf.map(x => nf(x, 0)).join(', ')}. Using the lecture's method (accumulated cash flow, whole years), in which year is the investment paid back?`, exp: `Accumulated cash flow: Y0: −${nf(inv, 0)}, ${rows.join(', ')}. It first becomes ≥ 0 in <b>year ${yr}</b>, so the payback period is year ${yr}.` }); },
    'pv': () => { const F = pick([1000, 1500, 2000, 5000, 10000]), r = pick([5, 8, 10, 12]), t = rnd(2, 6); const v = F * DF(r, t);
      return nat({ g: 'pv', wk: 3, topic: 't-cba', v, rel: 0.003, unit: 'Rs.', d: 2, text: `What is the present value of Rs. ${nf(F, 0)} received at the end of year ${t}, if the discount rate is ${r} %?`, exp: `P = F/(1+r)<sup>t</sup> = ${F}/(1.${String(r).padStart(2, '0')})<sup>${t}</sup> = <b>Rs. ${nf(v)}</b> (the lecture: Rs. 1500 at 10 % after 4 years = Rs. 1027.39).` }); },
    'exp-income': () => { const hi = pick([700, 800, 900]) * 1000, mid = pick([500, 600, 650]) * 1000, lo = pick([100, 150, 200]) * 1000; const ph = pick([0.1, 0.2]), pl = pick([0.2, 0.3]), pm = r2(1 - ph - pl, 2); const v = hi * ph + mid * pm + lo * pl;
      return nat({ g: 'exp-income', wk: 3, topic: 't-riskeval', v, rel: 0.002, unit: 'Rs./year', d: 0, text: `Annual sales income of a new product could be high Rs. ${nf(hi, 0)} (probability ${ph}), medium Rs. ${nf(mid, 0)} (probability ${pm}) or low Rs. ${nf(lo, 0)} (probability ${pl}). What is the expected annual income used in cost-benefit risk evaluation?`, exp: `Expected value = Σ income × probability = ${nf(hi, 0)}×${ph} + ${nf(mid, 0)}×${pm} + ${nf(lo, 0)}×${pl} = <b>Rs. ${nf(v, 0)}</b>.` }); },
    'dtree': () => { const p = pick([0.2, 0.25, 0.3, 0.4]); const eA = pick([60, 75, 80]) * 1000, eB = -pick([80, 100, 120]) * 1000, rA = pick([200, 250, 300]) * 1000, rB = -pick([40, 50, 60]) * 1000; const vE = (1 - p) * eA + p * eB, vR = p * rA + (1 - p) * rB; const best = vE >= vR ? 'extend' : 'replace';
      return nat({ g: 'dtree', wk: 3, topic: 't-riskeval', v: vE, rel: 0.002, unit: 'Rs.', d: 0, text: `Decision tree. Probability that the market expands = ${p}. Extending the existing system: NPV Rs. ${nf(eA, 0)} if the market does not expand, Rs. ${nf(eB, 0)} if it expands. Replacing the system: NPV Rs. ${nf(rA, 0)} if it expands, Rs. ${nf(rB, 0)} if it does not. What is the expected value of <i>extending</i> the system?`, exp: `E(extend) = ${1 - p}×${nf(eA, 0)} + ${p}×(${nf(eB, 0)}) = <b>Rs. ${nf(vE, 0)}</b>. E(replace) = ${p}×${nf(rA, 0)} + ${1 - p}×(${nf(rB, 0)}) = Rs. ${nf(vR, 0)}. Choose the higher: <b>${best}</b>.` }); },
    'pm-hours': () => { const pm = pick([2, 3, 5, 8, 12, 20]); const v = pm * 152;
      return nat({ g: 'pm-hours', wk: 4, topic: 't-estbasics', v, rel: 0, abs: 0.5, unit: 'person-hours', d: 0, text: `Using the COCOMO default, how many person-hours are in ${pm} person-months?`, exp: `1 person-month = 152 hours (19 days × 8 h). ${pm} × 152 = <b>${v}</b> hours.`, trap: [[pm * 160, 'used 20 days × 8 h'], [pm * 176, 'used 22 days × 8 h']] }); },
    'simple-effort': () => { const loc = pick([24, 30, 36, 45, 60, 75, 90, 120]) * 1000, prod = pick([300, 400, 500, 600]); const v = loc / prod;
      return nat({ g: 'simple-effort', wk: 4, topic: 't-esttech', v, rel: 0.005, unit: 'person-months', d: 1, text: `A transaction project is estimated at ${nf(loc, 0)} SLOC. Productivity on past projects was ${prod} SLOC per person-month. Using the simplistic model, what is the effort?`, exp: `Effort = size / productivity = ${nf(loc, 0)} / ${prod} = <b>${nf(v, 1)} person-months</b>.` }); },
    'three-point': () => { const o = rnd(2, 8), m = o + rnd(2, 8), p = m + rnd(2, 12); const v = (o + 4 * m + p) / 6;
      return nat({ g: 'three-point', wk: 4, topic: 't-esttech', v, rel: 0.003, unit: 'days', d: 2, text: `Weighted-average (three-point) estimating: optimistic ${o} days, most likely ${m} days, pessimistic ${p} days. What is the estimated effort?`, exp: `Estimate = (O + 4M + P)/6 = (${o} + 4×${m} + ${p})/6 = <b>${nf(v)}</b> days.`, trap: [[(o + m + p) / 3, 'simple average instead of weighting M by 4']] }); },
    'ufp': () => { const c = { EI: rnd(10, 60), EO: rnd(10, 60), EQ: rnd(5, 40), ILF: rnd(2, 12), EIF: rnd(1, 8) }; const v = Object.keys(c).reduce((s, k) => s + c[k] * W[k], 0);
      return nat({ g: 'ufp', wk: 4, topic: 't-fp', v, rel: 0, abs: 0.5, d: 0, text: `A system has ${c.EI} user inputs, ${c.EO} user outputs, ${c.EQ} user inquiries, ${c.ILF} internal logical files and ${c.EIF} external interface files, all of average complexity. What is the unadjusted function point count (UFP)?`, exp: `Average weights EI 4, EO 5, EQ 4, ILF 10, EIF 7: ${c.EI}×4 + ${c.EO}×5 + ${c.EQ}×4 + ${c.ILF}×10 + ${c.EIF}×7 = <b>${v}</b>.`, trap: [[c.EI * 3 + c.EO * 4 + c.EQ * 3 + c.ILF * 7 + c.EIF * 5, 'used the LOW complexity weights']] }); },
    'vaf': () => { const di = Array.from({ length: 14 }, () => rnd(0, 5)); const tdi = di.reduce((a, b) => a + b, 0); const v = 0.65 + 0.01 * tdi;
      return nat({ g: 'vaf', wk: 4, topic: 't-fp', v, rel: 0, abs: 0.0051, d: 2, text: `The degrees of influence of the 14 general system characteristics are ${di.join(', ')}. What is the value adjustment factor (VAF)?`, exp: `TDI = ${tdi}. VAF = 0.65 + 0.01 × TDI = 0.65 + ${(tdi / 100).toFixed(2)} = <b>${v.toFixed(2)}</b>. (VAF ranges from 0.65 to 1.35.)`, trap: [[tdi * 0.01, 'forgot the 0.65 constant']] }); },
    'afp': () => { const ufp = rnd(150, 900), k = rnd(1, 5), loc = pick([53, 59, 60, 70, 104]); const vaf = 0.65 + 0.14 * k, afp = ufp * vaf;
      return nat({ g: 'afp', wk: 4, topic: 't-fp', v: afp * loc / 1000, rel: 0.006, unit: 'KLOC', d: 2, text: `UFP = ${ufp}. Every one of the 14 general system characteristics has degree of influence ${k}. The language needs about ${loc} LOC per function point. What is the estimated size in KLOC?`, exp: `TDI = 14×${k} = ${14 * k}; VAF = 0.65 + ${(0.14 * k).toFixed(2)} = ${vaf.toFixed(2)}; AFP = ${ufp}×${vaf.toFixed(2)} = ${nf(afp)}; size = ${nf(afp)} × ${loc} = ${nf(afp * loc, 0)} LOC = <b>${nf(afp * loc / 1000)} KLOC</b>.` }); },
    'mk2': () => { const ni = rnd(40, 200), ne = rnd(20, 90), no = rnd(40, 200); const v = 0.58 * ni + 1.66 * ne + 0.26 * no;
      return nat({ g: 'mk2', wk: 4, topic: 't-fp', v, rel: 0.003, d: 2, text: `Symons Mark II: a system has ${ni} input data items, ${ne} entity accesses and ${no} output data items in total. What is the Mark II FP count?`, exp: `Mk II FP = 0.58·Ni + 1.66·Ne + 0.26·No = 0.58×${ni} + 1.66×${ne} + 0.26×${no} = <b>${nf(v)}</b>.` }); },
    'cosmic': () => { const e = rnd(3, 12), x = rnd(3, 12), r = rnd(2, 10), w = rnd(1, 8); const v = e + x + r + w;
      return nat({ g: 'cosmic', wk: 4, topic: 't-fp', v, rel: 0, abs: 0.5, unit: 'Cfsu', d: 0, text: `An embedded component has ${e} entries, ${x} exits, ${r} reads and ${w} writes of data groups. What is its COSMIC functional size?`, exp: `Each data movement counts 1 Cfsu: ${e} + ${x} + ${r} + ${w} = <b>${v} Cfsu</b>.` }); },
    'appcomp': () => { const scr = [rnd(2, 8), rnd(1, 6), rnd(0, 4)], rep = [rnd(1, 5), rnd(0, 4), rnd(0, 3)], mod = rnd(0, 4), reuse = pick([0, 10, 20, 25, 30]), prod = pick([4, 7, 13, 25, 50]); const nap = scr[0] + 2 * scr[1] + 3 * scr[2] + 2 * rep[0] + 5 * rep[1] + 8 * rep[2] + 10 * mod; const v = nap * (1 - reuse / 100) / prod;
      return nat({ g: 'appcomp', wk: 5, topic: 't-cocomo2', v, rel: 0.01, unit: 'person-months', d: 2, text: `COCOMO II application composition: screens ${scr[0]} simple, ${scr[1]} medium, ${scr[2]} complex; reports ${rep[0]} simple, ${rep[1]} medium, ${rep[2]} complex; ${mod} 3GL modules. ${reuse} % reuse is expected and productivity is ${prod} NAP/month. Effort?`, exp: `Weights: screens 1/2/3, reports 2/5/8, modules 10. NAP = ${scr[0]} + 2×${scr[1]} + 3×${scr[2]} + 2×${rep[0]} + 5×${rep[1]} + 8×${rep[2]} + 10×${mod} = ${nap}. PM = NAP(1 − %reuse/100)/PROD = ${nap}×${(1 - reuse / 100).toFixed(2)}/${prod} = <b>${nf(v)} PM</b>.` }); },
    'cocomo-effort': () => { const mode = pick(Object.keys(MODES)), kloc = pick([8, 10, 12, 16, 20, 25, 32, 40, 50, 60, 80, 100]); const [a, b] = MODES[mode]; const v = a * kloc ** b;
      return nat({ g: 'cocomo-effort', wk: 5, topic: 't-cocomo', v, rel: 0.01, unit: 'PM', d: 1, text: `Basic COCOMO: a ${mode} product of ${kloc} KLOC. What is the nominal effort in person-months?`, exp: `Effort = a·(KLOC)<sup>b</sup> with ${mode} a = ${a}, b = ${b}: ${a}×${kloc}<sup>${b}</sup> = <b>${nf(v, 1)} PM</b>.`, trap: [[a * kloc, 'forgot the exponent'], [a * (kloc * 1000) ** b / 1000, 'used LOC instead of KLOC']] }); },
    'cocomo-tdev': () => { const mode = pick(Object.keys(MODES)), E = pick([20, 30, 45, 60, 91, 120, 200, 300, 394]); const c = MODES[mode][2]; const v = 2.5 * E ** c;
      return nat({ g: 'cocomo-tdev', wk: 5, topic: 't-cocomo', v, rel: 0.01, unit: 'months', d: 1, text: `Basic COCOMO, ${mode} mode: the effort has been estimated as ${E} person-months. What is the nominal development time?`, exp: `Tdev = 2.5 × (Effort)<sup>c</sup>, c = ${c} for ${mode}: 2.5 × ${E}<sup>${c}</sup> = <b>${nf(v, 1)} months</b>.` }); },
    'cocomo-staff': () => { const mode = pick(Object.keys(MODES)), kloc = pick([7.5, 10, 20, 32, 50, 64]); const [a, b, c] = MODES[mode]; const E = a * kloc ** b, T = 2.5 * E ** c, v = E / T;
      return nat({ g: 'cocomo-staff', wk: 5, topic: 't-cocomo', v, rel: 0.015, unit: 'persons', d: 1, text: `Basic COCOMO, ${mode} mode, ${kloc} KLOC. What is the average staff size (effort ÷ development time)?`, exp: `E = ${a}×${kloc}<sup>${b}</sup> = ${nf(E, 1)} PM; T = 2.5×${nf(E, 1)}<sup>${c}</sup> = ${nf(T, 1)} months; average staff = E/T = <b>${nf(v, 1)}</b>.` }); },
    'cocomo-cost': () => { const kloc = pick([10, 20, 32, 40]), sal = pick([15, 20, 25, 50]) * 1000; const E = 2.4 * kloc ** 1.05, v = E * sal;
      return nat({ g: 'cocomo-cost', wk: 5, topic: 't-cocomo', v: v / 1e5, rel: 0.012, unit: 'lakh Rs.', d: 2, text: `An organic product of ${kloc} KLOC is to be built. A developer costs Rs. ${nf(sal, 0)} per month. Using basic COCOMO, what is the staff cost in lakh rupees?`, exp: `E = 2.4×${kloc}<sup>1.05</sup> = ${nf(E, 1)} PM. Cost = ${nf(E, 1)} × ${nf(sal, 0)} = Rs. ${nf(v, 0)} = <b>${nf(v / 1e5)} lakh</b>.` }); },
    'cocomo-int': () => { const E0 = pick([26.9, 45, 60, 91, 120]); const D = shuffle([['analyst capability low', 1.19], ['analyst capability high', 0.86], ['required reliability very high', 1.40], ['required reliability high', 1.15], ['product complexity high', 1.15], ['storage constraint high', 1.06], ['execution time constraint high', 1.11], ['programmer capability low', 1.17], ['application experience low', 1.13], ['modern programming practices high', 0.91], ['use of software tools high', 0.91], ['language experience high', 0.95]]).slice(0, 3); const eaf = D.reduce((p, d) => p * d[1], 1), v = E0 * eaf;
      return nat({ g: 'cocomo-int', wk: 5, topic: 't-cocomo', v, rel: 0.01, unit: 'PM', d: 1, text: `Basic COCOMO gives ${E0} PM. Cost-driver ratings: ${D.map(d => `${d[0]} (${d[1]})`).join(', ')}; all others nominal. Intermediate COCOMO effort?`, exp: `EAF = ${D.map(d => d[1]).join(' × ')} = ${eaf.toFixed(3)}. Effort = ${E0} × ${eaf.toFixed(3)} = <b>${nf(v, 1)} PM</b>. Multipliers > 1 scale up, < 1 scale down.` }); },
    'cocomo2-exp': () => { const S = { PREC: [6.20, 4.96, 3.72, 2.48, 1.24, 0], FLEX: [5.07, 4.05, 3.04, 2.03, 1.01, 0], RESL: [7.07, 5.65, 4.24, 2.83, 1.41, 0], TEAM: [5.48, 4.38, 3.29, 2.19, 1.10, 0], PMAT: [7.80, 6.24, 4.68, 3.12, 1.56, 0] }; const lv = ['very low', 'low', 'nominal', 'high', 'very high', 'extra high']; const pickd = Object.keys(S).map(k => { const i = rnd(0, 4); return [k, lv[i], S[k][i]]; }); const sum = pickd.reduce((s, x) => s + x[2], 0), B = 0.91 + 0.01 * sum, kloc = pick([8, 10, 20, 30, 50]), v = 2.94 * kloc ** B;
      return nat({ g: 'cocomo2-exp', wk: 5, topic: 't-cocomo2', v, rel: 0.012, unit: 'PM', d: 1, text: `COCOMO II (all effort multipliers nominal): ${kloc} KSLOC; scale factors ${pickd.map(x => `${x[0]} ${x[1]} (${x[2]})`).join(', ')}. Effort = 2.94 × size<sup>B</sup>, B = 0.91 + 0.01 Σ SF. Effort?`, exp: `Σ SF = ${sum.toFixed(2)}; B = 0.91 + ${(sum / 100).toFixed(4)} = ${B.toFixed(4)}; effort = 2.94 × ${kloc}<sup>${B.toFixed(4)}</sup> = <b>${nf(v, 1)} PM</b>. (Lecture: Σ = 17.57 → B = 1.0857; 10 KLOC → 35.8 PM.)` }); },
    'halstead': () => { const n1 = rnd(8, 20), n2 = rnd(6, 25), N1 = n1 * rnd(2, 5), N2 = n2 * rnd(2, 4); const N = N1 + N2, eta = n1 + n2, V = N * Math.log2(eta);
      return nat({ g: 'halstead', wk: 5, topic: 't-halstead', v: V, rel: 0.005, unit: 'bits', d: 1, text: `A program uses η₁ = ${n1} unique operators, η₂ = ${n2} unique operands, N₁ = ${N1} total operators and N₂ = ${N2} total operands. What is Halstead's program volume V?`, exp: `Length N = N₁ + N₂ = ${N}; vocabulary η = η₁ + η₂ = ${eta}; V = N log₂η = ${N} × ${Math.log2(eta).toFixed(4)} = <b>${nf(V, 1)} bits</b>.`, trap: [[N * Math.log10(eta), 'used log₁₀ instead of log₂'], [eta * Math.log2(N), 'swapped N and η']] }); },
    'halstead-e': () => { const V = rnd(500, 3000), n2 = rnd(2, 5), Vs = (2 + n2) * Math.log2(2 + n2), v = V * V / Vs;
      return nat({ g: 'halstead-e', wk: 5, topic: 't-halstead', v: v / 18 / 3600, rel: 0.01, unit: 'hours', d: 2, text: `A program has volume V = ${V} bits. The algorithm has ${n2} input/output parameters, so the most succinct program is f(d1…d${n2}). Using S = 18 mental discriminations per second, what is Halstead's estimated programming time in hours?`, exp: `V* = (2 + η₂*)log₂(2 + η₂*) = ${2 + n2}×log₂${2 + n2} = ${Vs.toFixed(2)}. L = V*/V; E = V/L = V²/V* = ${nf(v, 0)}. T = E/S = ${nf(v / 18, 0)} s = <b>${nf(v / 18 / 3600)} h</b>.` }); },
    'putnam': () => { const t1 = pick([12, 18, 24, 36]), f = pick([0.5, 0.75, 2 / 3, 0.8]); const t2 = Math.round(t1 * f); const v = (t1 / t2) ** 4;
      return nat({ g: 'putnam', wk: 5, topic: 't-staffing', v, rel: 0.01, unit: 'times', d: 2, text: `A product's development time was estimated at ${t1} months. The customer wants it in ${t2} months. By what factor does the effort increase according to Putnam's model?`, exp: `Putnam: K ∝ 1/t<sub>d</sub><sup>4</sup>, so K₂/K₁ = (t₁/t₂)<sup>4</sup> = (${t1}/${t2})<sup>4</sup> = <b>${nf(v)}</b>. (Jensen would give (${t1}/${t2})² = ${nf((t1 / t2) ** 2)}.)`, trap: [[(t1 / t2) ** 2, 'used Jensen (square) instead of Putnam (fourth power)']] }); },
    'jensen': () => { const t1 = pick([12, 18, 24]), t2 = pick([6, 8, 9]); const v = (t1 / t2) ** 2;
      return nat({ g: 'jensen', wk: 5, topic: 't-staffing', v, rel: 0.01, unit: 'times', d: 2, text: `Estimated development time ${t1} months, required ${t2} months. Increase in effort according to Jensen's model?`, exp: `Jensen: K ∝ 1/t<sub>d</sub>², ratio = (${t1}/${t2})² = <b>${nf(v)}</b> (Putnam would give (${t1}/${t2})⁴ = ${nf((t1 / t2) ** 4)}).`, trap: [[(t1 / t2) ** 4, 'used Putnam (fourth power) instead of Jensen (square)']] }); },
    'cpm-T': () => { const net = network(rnd(6, 8));
      return nat({ g: 'cpm-T', wk: 6, topic: 't-cpm', v: net.T, rel: 0, abs: 0.01, unit: 'weeks', d: 0, text: `Find the minimum project duration.` + netTable(net), exp: `Forward pass (ES = max EF of predecessors):` + netWork(net) + `Duration = largest EF = <b>${net.T} weeks</b>; critical path ${net.paths.map(p => p.join('-')).join(' and ')}.` }); },
    'cpm-float': () => { let net, a; do { net = network(rnd(6, 8)); a = pick(net.acts.filter(x => x.fl > 0)); } while (!a);
      return nat({ g: 'cpm-float', wk: 6, topic: 't-cpm', v: a.fl, rel: 0, abs: 0.01, unit: 'weeks', d: 0, text: `What is the total float of activity <b>${a.id}</b>?` + netTable(net), exp: netWork(net) + `Float(${a.id}) = LS − ES = ${a.ls} − ${a.es} = <b>${a.fl}</b>.` }); },
    'float-basic': () => { const es = rnd(0, 20), d = rnd(3, 15), lf = es + d + rnd(0, 15); const v = lf - d - es;
      return nat({ g: 'float-basic', wk: 6, topic: 't-cpm', v, rel: 0, abs: 0.01, unit: 'days', d: 0, text: `An activity has ES = ${es} days, duration ${d} days and LF = ${lf} days. What is its float?`, exp: `EF = ES + d = ${es + d}; LS = LF − d = ${lf - d}; float = LS − ES = LF − ES − d = <b>${v}</b>.` }); },
    'pert-te': () => { const a = rnd(2, 8), m = a + rnd(1, 6), b = m + rnd(2, 12); const v = (a + 4 * m + b) / 6;
      return nat({ g: 'pert-te', wk: 7, topic: 't-pert', v, rel: 0.003, unit: 'days', d: 2, text: `PERT estimates for an activity: optimistic a = ${a}, most likely m = ${m}, pessimistic b = ${b} days. Expected time t<sub>e</sub>?`, exp: `t<sub>e</sub> = (a + 4m + b)/6 = (${a} + ${4 * m} + ${b})/6 = <b>${nf(v)}</b>. Variance = ((b − a)/6)² = ${nf(((b - a) / 6) ** 2, 3)}.` }); },
    'pert-var': () => { const a = rnd(2, 8), m = a + rnd(1, 6), b = m + rnd(4, 14); const v = ((b - a) / 6) ** 2;
      return nat({ g: 'pert-var', wk: 7, topic: 't-pert', v, rel: 0.005, unit: 'days²', d: 3, text: `PERT: a = ${a}, m = ${m}, b = ${b} days. What is the variance of the activity duration?`, exp: `σ² = ((b − a)/6)² = (${b - a}/6)² = <b>${nf(v, 3)}</b>; σ = ${nf((b - a) / 6, 3)}.`, trap: [[(b - a) / 6, 'gave the standard deviation instead of the variance']] }); },
    'paths': () => { const n = rnd(4, 15); const v = n * (n - 1) / 2;
      return nat({ g: 'paths', wk: 7, topic: 't-org', v, rel: 0, abs: 0.01, d: 0, text: `In a democratic team of ${n} members where everyone talks to everyone, how many communication paths are there?`, exp: `n(n − 1)/2 = ${n}×${n - 1}/2 = <b>${v}</b>. Paths grow ≈ n², which is why democratic teams do not scale.` }); },
    're': () => { const loss = pick([2, 5, 8, 10, 20, 50]) * 1e5, p = pick([0.01, 0.02, 0.05, 0.1, 0.2, 0.3]); const v = loss * p;
      return nat({ g: 're', wk: 7, topic: 't-risk', v, rel: 0.001, unit: 'Rs.', d: 0, text: `A risk would cause damage of Rs. ${nf(loss, 0)} with probability ${p}. What is its risk exposure?`, exp: `RE = potential damage × probability = ${nf(loss, 0)} × ${p} = <b>Rs. ${nf(v, 0)}</b>.` }); },
    'rrl': () => { const loss = pick([100, 200, 400, 500]) * 1000, p1 = pick([0.02, 0.04, 0.05, 0.1]), p2 = r2(p1 * pick([0.25, 0.5]), 4), cost = pick([500, 1000, 1500, 2000, 4000]); const v = (loss * p1 - loss * p2) / cost;
      return nat({ g: 'rrl', wk: 7, topic: 't-risk', v, rel: 0.005, d: 2, text: `A fire risk could cause Rs. ${nf(loss, 0)} of damage with probability ${p1 * 100} %. A fire alarm costing Rs. ${nf(cost, 0)} reduces the probability to ${nf(p2 * 100, 2)} %. What is the risk reduction leverage (RRL)?`, exp: `RE<sub>before</sub> = ${nf(loss * p1, 0)}; RE<sub>after</sub> = ${nf(loss * p2, 0)}; RRL = (RE<sub>before</sub> − RE<sub>after</sub>)/cost = ${nf(loss * (p1 - p2), 0)}/${cost} = <b>${nf(v)}</b> → ${v > 1 ? 'worth doing (RRL > 1)' : 'not worth it (RRL < 1)'}.` }); },
    'eva-sv': () => { const pv = pick([40, 50, 55, 60, 80]) * 1000, ev = pv - pick([5, 8, 10, 15]) * 1000; const v = ev - pv;
      return nat({ g: 'eva-sv', wk: 9, topic: 't-eva', v, rel: 0, abs: 1, unit: 'Rs.', d: 0, text: `Work with a planned value of Rs. ${nf(pv, 0)} should have been completed by now, but the earned value is only Rs. ${nf(ev, 0)}. What is the schedule variance (SV)? (Give the sign.)`, exp: `SV = EV − PV = ${nf(ev, 0)} − ${nf(pv, 0)} = <b>${nf(v, 0)}</b>: negative ⇒ behind schedule.`, trap: [[-v, 'sign reversed (PV − EV)']] }); },
    'eva-cpi': () => { const ev = pick([30, 35, 40, 45, 50]) * 1000, ac = ev + pick([-5, 5, 10, 15, 20]) * 1000; const v = ev / ac;
      return nat({ g: 'eva-cpi', wk: 9, topic: 't-eva', v, rel: 0, abs: 0.006, d: 2, text: `EV = Rs. ${nf(ev, 0)} and the actual cost of the work done is Rs. ${nf(ac, 0)}. What is the cost performance index (CPI)?`, exp: `CPI = EV/AC = ${nf(ev, 0)}/${nf(ac, 0)} = <b>${v.toFixed(2)}</b> → ${v < 1 ? 'over budget' : 'within budget'}.`, trap: [[ac / ev, 'inverted (AC/EV)']] }); },
    'eva-eac': () => { const bac = pick([100, 150, 200, 500]) * 1000, cpi = pick([0.64, 0.75, 0.8, 0.9, 1.25]); const v = bac / cpi;
      return nat({ g: 'eva-eac', wk: 9, topic: 't-eva', v, rel: 0.003, unit: 'Rs.', d: 0, text: `Budget at completion (BAC) is Rs. ${nf(bac, 0)} and the current CPI is ${cpi}. What is the estimate at completion (EAC)?`, exp: `EAC = BAC/CPI = ${nf(bac, 0)}/${cpi} = <b>Rs. ${nf(v, 0)}</b>.`, trap: [[bac * cpi, 'multiplied instead of divided']] }); },
    'eva-teac': () => { const sac = pick([12, 18, 23, 24, 30]), spi = pick([0.8, 0.88, 0.9, 1.2]); const v = sac / spi;
      return nat({ g: 'eva-teac', wk: 9, topic: 't-eva', v, rel: 0.003, unit: 'months', d: 2, text: `Schedule at completion (SAC) = ${sac} months, SPI = ${spi}. Time estimate at completion (TEAC)?`, exp: `TEAC = SAC/SPI = ${sac}/${spi} = <b>${nf(v)} months</b>.` }); },
    'eva-pct': () => { const bac = pick([100, 200, 400, 600]) * 1000, dur = 12, m = pick([3, 4, 6]), pct = pick([20, 25, 30, 40, 50]), ac = Math.round(bac * pct / 100 * pick([0.8, 0.9, 1.1, 1.3]) / 1000) * 1000; const pvp = m / dur * 100, pv = pvp / 100 * bac, ev = pct / 100 * bac; const spi = ev / pv;
      return nat({ g: 'eva-pct', wk: 9, topic: 't-eva', v: spi, rel: 0, abs: 0.006, d: 2, text: `A project of Rs. ${nf(bac, 0)} is planned to finish in 12 months with work spread evenly. After ${m} months it is ${pct} % complete and Rs. ${nf(ac, 0)} has been spent. What is the SPI?`, exp: `PV = ${m}/12 × BAC = ${nf(pvp)} % × ${nf(bac, 0)} = ${nf(pv, 0)}; EV = ${pct} % × BAC = ${nf(ev, 0)}; SPI = EV/PV = <b>${spi.toFixed(2)}</b> (${spi >= 1 ? 'ahead of schedule' : 'behind schedule'}); CPI = EV/AC = ${(ev / ac).toFixed(2)} (${ev / ac >= 1 ? 'within budget' : 'over budget'}).` }); },
    'fp-price': () => { const fp = pick([1800, 2300, 2700, 3200, 3700, 4200]); const S = [[2000, 900], [2500, 1000], [3000, 1040], [3500, 1070], [4000, 1100], [4500, 1140], [5000, 1200]]; let left = fp, lo = 0, tot = 0, parts = []; for (const [hi, p] of S) { const n = Math.min(left, hi - lo); if (n <= 0) break; tot += n * p; parts.push(`${n}×${p}`); left -= n; lo = hi; }
      return nat({ g: 'fp-price', wk: 10, topic: 't-contract', v: tot, rel: 0, abs: 1, unit: 'Rs.', d: 0, text: `Fixed price per unit delivered: the supplier charges Rs. 900/FP up to 2000 FP, Rs. 1000/FP for 2001-2500, 1040 for 2501-3000, 1070 for 3001-3500, 1100 for 3501-4000, 1140 for 4001-4500. What is the charge for a ${fp}-FP system?`, exp: `Charge slab by slab: ${parts.join(' + ')} = <b>Rs. ${nf(tot, 0)}</b> (lecture: 2700 FP → Rs. 25,08,000).`, trap: [[fp * S.find(s => fp <= s[0])[1], 'charged the whole system at the top slab rate']] }); },
    'pofod': () => { const d = pick([1000, 2000, 4000, 5000, 10000]), f = rnd(1, 25); const v = f / d * 100;
      return nat({ g: 'pofod', wk: 12, topic: 't-reliab', v, rel: 0.002, unit: '%', d: 3, text: `Out of ${nf(d, 0)} service requests a system failed ${f} times. What is its POFOD in percent?`, exp: `POFOD = failures/demands = ${f}/${d} = ${(f / d).toFixed(4)} = <b>${nf(v, 3)} %</b>. It does not involve time.`, trap: [[f / d, 'gave a fraction instead of a percentage']] }); },
    'avail': () => { const mtbf = pick([10, 20, 30, 45, 60, 90]), mttr = pick([2, 4, 5, 8, 12, 24]), inDays = Math.random() < .5; const MT = inDays ? mtbf * 24 : mtbf; const v = MT / (MT + mttr) * 100;
      return nat({ g: 'avail', wk: 12, topic: 't-reliab', v, rel: 0, abs: 0.06, unit: '%', d: 2, text: `MTBF = ${mtbf} ${inDays ? 'days' : 'hours'}, MTTR = ${mttr} hours. What is the inherent availability (in %)?`, exp: `${inDays ? `Convert to hours: MTBF = ${mtbf}×24 = ${MT} h. ` : ''}A = MTBF/(MTBF + MTTR) = ${MT}/(${MT} + ${mttr}) = <b>${nf(v)} %</b>.`, trap: inDays ? [[mtbf / (mtbf + mttr) * 100, 'mixed days and hours']] : [] }); },
    'mttf': () => { let t = 0; const ts = Array.from({ length: rnd(5, 7) }, () => (t += rnd(20, 120))); const v = (ts[ts.length - 1] - ts[0]) / (ts.length - 1);
      return nat({ g: 'mttf', wk: 12, topic: 't-reliab', v, rel: 0.003, unit: 'hours', d: 2, text: `Failures were observed at t = ${ts.join(', ')} hours of operation. What is the MTTF?`, exp: `MTTF = Σ(t<sub>i+1</sub> − t<sub>i</sub>)/(n − 1) = (${ts[ts.length - 1]} − ${ts[0]})/${ts.length - 1} = <b>${nf(v)} h</b>.`, trap: Math.abs(ts[ts.length - 1] / ts.length / v - 1) > 0.02 ? [[ts[ts.length - 1] / ts.length, 'divided total time by n']] : [] }); },
    'dpmo': () => { const units = pick([500, 1000, 2000, 5000]), opp = pick([4, 5, 8, 10]), def = rnd(2, 60); const v = def / (units * opp) * 1e6;
      return nat({ g: 'dpmo', wk: 12, topic: 't-cmmi', v, rel: 0.003, unit: 'DPMO', d: 1, text: `${units} units were inspected, each with ${opp} defect opportunities, and ${def} defects were found. Defects per million opportunities? (Six Sigma allows 3.4.)`, exp: `DPMO = defects/(units × opportunities) × 10⁶ = ${def}/(${units}×${opp}) × 10⁶ = <b>${nf(v, 1)}</b>. (5σ ≈ 230, 4σ ≈ 6210.)` }); },
    'vc': () => { const items = shuffle([['profit reports', 9, 2], ['online database', 1, 9], ['ad hoc enquiry', 5, 5], ['purchasing plans', 9, 4], ['profit-based pay', 9, 1], ['mobile alerts', 6, 3], ['audit trail', 4, 2], ['dashboard', 7, 5]]).slice(0, 5); const best = items.slice().sort((a, b) => b[1] / b[2] - a[1] / a[2]);
      return mcq({ g: 'vc', wk: 2, topic: 't-proto', text: `Incremental delivery: value (1-10) and cost (0-10) of candidate increments are ${items.map(i => `${i[0]} (V ${i[1]}, C ${i[2]})`).join('; ')}. Which increment should be delivered first?`, opts: best.map(i => i[0]), ans: [0], exp: `Rank by V/C: ${best.map(i => `${i[0]} ${nf(i[1] / i[2])}`).join(' > ')}. Highest ratio first.` }); },
  };
  const names = Object.keys(G);
  function make(name) { const f = G[name]; return f ? f() : null; }

  /* ---------- Section-II style passages: one scenario, several linked questions */
  const P = {
    invest: () => { const r = 10, inv = pick([100, 120, 150]) * 1000; const cf = Array.from({ length: 5 }, () => Math.round(inv * (0.12 + Math.random() * 0.3) / 1000) * 1000); const net = cf.reduce((a, b) => a + b, 0) - inv; let acc = -inv, pb = 0; cf.forEach((c, i) => { acc += c; if (!pb && acc >= 0) pb = i + 1; }); const dfs = [0.9091, 0.8264, 0.7513, 0.6830, 0.6209], npv = -inv + cf.reduce((s, c, t) => s + c * dfs[t], 0);
      const txt = `<b class="k">Case: CityCab booking system.</b> CityCab invests Rs. ${nf(inv, 0)} (year 0) in a new booking system. Expected net cash inflows at the end of years 1-5 are Rs. ${cf.map(x => nf(x, 0)).join(', ')}. The company's discount rate is ${r} % (discount factors 0.9091, 0.8264, 0.7513, 0.6830, 0.6209 for years 1-5).`;
      return { title: 'Investment appraisal', topic: 't-cba', html: txt, qs: [
        nat({ g: 'p-net', wk: 3, topic: 't-cba', v: net, rel: 0, abs: 1, unit: 'Rs.', d: 0, text: 'What is the net profit over the five years?', exp: `Net profit = Σ inflows − investment = ${nf(net + inv, 0)} − ${nf(inv, 0)} = <b>${nf(net, 0)}</b>.` }),
        nat({ g: 'p-roi', wk: 3, topic: 't-cba', v: net / 5 / inv * 100, rel: 0.005, unit: '%', d: 2, text: 'What is the ROI (in %)?', exp: `ROI = (net profit/5)/investment × 100 = ${nf(net / 5, 0)}/${nf(inv, 0)} × 100 = <b>${nf(net / 5 / inv * 100)} %</b>.` }),
        nat({ g: 'p-pb', wk: 3, topic: 't-cba', v: pb || 6, rel: 0, abs: 0.01, unit: 'year', d: 0, text: 'In which year is the investment paid back (accumulated cash flow first ≥ 0)? Enter 6 if not within 5 years.', exp: `Accumulate the cash flows year by year from −${nf(inv, 0)}; the first year the total becomes non-negative is <b>${pb || '— (not within 5 years → 6)'}</b>.` }),
        nat({ g: 'p-npv', wk: 3, topic: 't-cba', v: npv, rel: 0, abs: Math.max(150, inv * 0.004), unit: 'Rs.', d: 0, text: 'What is the NPV at 10 %?', exp: `NPV = −${nf(inv, 0)} + ${cf.map((c, t) => `${nf(c, 0)}×${dfs[t]}`).join(' + ')} = <b>${nf(npv, 0)}</b>.` }),
        mcq({ g: 'p-tech', wk: 3, topic: 't-cba', text: 'Which statement about these techniques is correct?', opts: ['Only NPV accounts for the timing of the cash flows', 'ROI accounts for the time value of money', 'Payback considers income after break-even', 'Net profit is the best measure for comparing projects of different sizes'], ans: [0], exp: 'Net profit, payback and ROI ignore the timing of cash flows; payback also ignores income after break-even. NPV (and IRR) discount the cash flows.' })] };
    },
    size: () => { const c = { EI: rnd(20, 60), EO: rnd(20, 50), EQ: rnd(10, 35), ILF: rnd(4, 10), EIF: rnd(2, 6) }; const ufp = Object.keys(c).reduce((s, k) => s + c[k] * W[k], 0); const tdi = rnd(30, 50), vaf = 0.65 + tdi / 100, afp = ufp * vaf, loc = pick([53, 59, 70]); const kloc = afp * loc / 1000, E = 2.4 * kloc ** 1.05, T = 2.5 * E ** 0.38, sal = pick([40, 50, 60]) * 1000;
      const txt = `<b class="k">Case: Hostel management portal.</b> An analysis of the requirements found ${c.EI} external inputs, ${c.EO} external outputs, ${c.EQ} external inquiries, ${c.ILF} internal logical files and ${c.EIF} external interface files, all of average complexity (weights 4, 5, 4, 10, 7). The total degree of influence of the 14 general system characteristics is ${tdi}. The implementation language needs about ${loc} LOC per FP. The team is experienced with similar business systems (organic mode). A developer costs Rs. ${nf(sal, 0)} per month.`;
      return { title: 'Sizing and estimating', topic: 't-fp', html: txt, qs: [
        nat({ g: 'p-ufp', wk: 4, topic: 't-fp', v: ufp, rel: 0, abs: 0.5, d: 0, text: 'Unadjusted function points (UFP)?', exp: `${c.EI}×4 + ${c.EO}×5 + ${c.EQ}×4 + ${c.ILF}×10 + ${c.EIF}×7 = <b>${ufp}</b>.` }),
        nat({ g: 'p-afp', wk: 4, topic: 't-fp', v: afp, rel: 0.004, d: 1, text: 'Adjusted function points (AFP)?', exp: `VAF = 0.65 + 0.01×${tdi} = ${vaf.toFixed(2)}; AFP = ${ufp}×${vaf.toFixed(2)} = <b>${nf(afp, 1)}</b>.` }),
        nat({ g: 'p-kloc', wk: 4, topic: 't-fp', v: kloc, rel: 0.006, unit: 'KLOC', d: 2, text: 'Estimated size in KLOC?', exp: `${nf(afp, 1)} × ${loc} = ${nf(afp * loc, 0)} LOC = <b>${nf(kloc)} KLOC</b>.` }),
        nat({ g: 'p-eff', wk: 5, topic: 't-cocomo', v: E, rel: 0.012, unit: 'PM', d: 1, text: 'Basic COCOMO effort (person-months)?', exp: `Organic: 2.4 × ${nf(kloc)}<sup>1.05</sup> = <b>${nf(E, 1)} PM</b>.` }),
        nat({ g: 'p-tdev', wk: 5, topic: 't-cocomo', v: T, rel: 0.012, unit: 'months', d: 1, text: 'Nominal development time (months)?', exp: `2.5 × ${nf(E, 1)}<sup>0.38</sup> = <b>${nf(T, 1)} months</b>; average staff ${nf(E / T, 1)}; cost ≈ Rs. ${nf(E * sal, 0)}.` })] };
    },
    sched: () => { const net = network(7); const a = pick(net.acts.filter(x => x.fl > 0)) || net.acts[1]; const b = pick(net.acts.filter(x => x.pre.length > 1)) || net.acts[net.acts.length - 1]; const delay = a.fl + rnd(1, 3);
      const cp = net.paths[0] ? net.paths[0].join('-') : ''; const cps = net.paths.map(p => p.join('-')); let wrong = shuffle(net.all.filter(x => x[1] < net.T).map(x => x[0].join('-'))).filter((v, i, a) => a.indexOf(v) === i).slice(0, 3); ['A-B-D-G', 'A-C-E-G', 'B-D-F', 'A-C-F-G', 'B-C-E-G', 'A-E-G'].forEach(x => { if (wrong.length < 3 && !cps.includes(x) && !wrong.includes(x)) wrong.push(x); });
      return { title: 'Activity network', topic: 't-cpm', html: `<b class="k">Case: Office relocation IT project.</b> The activities, durations (weeks) and immediate predecessors are:` + netTable(net), qs: [
        nat({ g: 'p-T', wk: 6, topic: 't-cpm', v: net.T, rel: 0, abs: 0.01, unit: 'weeks', d: 0, text: 'What is the minimum project duration?', exp: netWork(net) + `Duration = <b>${net.T}</b>.` }),
        mcq({ g: 'p-cp', wk: 6, topic: 't-cpm', text: 'Which is a critical path?', opts: [cp].concat(wrong), ans: [0], exp: `Zero-float chain from start to finish: <b>${net.paths.map(p => p.join('-')).join(', ')}</b>.` }),
        nat({ g: 'p-fl', wk: 6, topic: 't-cpm', v: a.fl, rel: 0, abs: 0.01, unit: 'weeks', d: 0, text: `What is the total float of activity ${a.id}?`, exp: `LS − ES = ${a.ls} − ${a.es} = <b>${a.fl}</b>.` }),
        nat({ g: 'p-es', wk: 6, topic: 't-cpm', v: b.es, rel: 0, abs: 0.01, unit: 'weeks', d: 0, text: `What is the earliest start (ES) of activity ${b.id}?`, exp: `ES = max EF of predecessors ${b.pre.join(', ')} = <b>${b.es}</b>.` }),
        nat({ g: 'p-delay', wk: 6, topic: 't-cpm', v: net.T + (delay - a.fl), rel: 0, abs: 0.01, unit: 'weeks', d: 0, text: `If activity ${a.id} is delayed by ${delay} weeks (all else unchanged), what is the new project duration?`, exp: `${a.id} has ${a.fl} weeks of float; a ${delay}-week delay uses it and pushes the end date by ${delay - a.fl}: <b>${net.T + delay - a.fl} weeks</b>.` })] };
    },
    eva: () => { const bac = pick([200, 240, 300, 400]) * 1000, m = pick([3, 4, 5, 6]), dur = 12, pct = pick([20, 25, 30, 35, 45, 50]), ac = Math.round(bac * (pct / 100) * pick([0.8, 0.9, 1.1, 1.25, 1.4]) / 1000) * 1000; const pv = bac * m / dur, ev = bac * pct / 100; const sv = ev - pv, cv = ev - ac, spi = ev / pv, cpi = ev / ac, eac = bac / cpi;
      const st = (spi < 1 ? 'behind schedule' : 'ahead of schedule') + ' and ' + (cpi < 1 ? 'over budget' : 'within budget');
      return { title: 'Earned value status', topic: 't-eva', html: `<b class="k">Case: Library automation.</b> Budget at completion Rs. ${nf(bac, 0)}, planned duration 12 months with work spread evenly. At the end of month ${m} the project is ${pct} % complete and Rs. ${nf(ac, 0)} has actually been spent.`, qs: [
        nat({ g: 'p-pv', wk: 9, topic: 't-eva', v: pv, rel: 0, abs: 1, unit: 'Rs.', d: 0, text: 'Planned value (PV) now?', exp: `PV = ${m}/12 × ${nf(bac, 0)} = <b>${nf(pv, 0)}</b>.` }),
        nat({ g: 'p-sv', wk: 9, topic: 't-eva', v: sv, rel: 0, abs: 1, unit: 'Rs.', d: 0, text: 'Schedule variance SV (with sign)?', exp: `EV = ${pct} % × BAC = ${nf(ev, 0)}; SV = EV − PV = <b>${nf(sv, 0)}</b>.` }),
        nat({ g: 'p-cpi', wk: 9, topic: 't-eva', v: cpi, rel: 0, abs: 0.006, d: 2, text: 'Cost performance index (CPI)?', exp: `CPI = EV/AC = ${nf(ev, 0)}/${nf(ac, 0)} = <b>${cpi.toFixed(2)}</b>.` }),
        nat({ g: 'p-eac', wk: 9, topic: 't-eva', v: eac, rel: 0.01, unit: 'Rs.', d: 0, text: 'Estimate at completion (EAC = BAC/CPI)?', exp: `EAC = ${nf(bac, 0)}/${cpi.toFixed(3)} = <b>${nf(eac, 0)}</b>.` }),
        mcq({ g: 'p-st', wk: 9, topic: 't-eva', text: 'Overall status of the project?', opts: [st].concat(['ahead of schedule and within budget', 'behind schedule and over budget', 'ahead of schedule and over budget', 'behind schedule and within budget'].filter(x => x !== st)), ans: [0], exp: `SPI = ${spi.toFixed(2)}, CPI = ${cpi.toFixed(2)} → <b>${st}</b>. (CV = ${nf(cv, 0)}.)` })] };
    },
    risk: () => { const R = [['Key developer leaves', pick([0.1, 0.2, 0.3]), pick([4, 5, 8]) * 1e5], ['Requirements change late', pick([0.3, 0.4, 0.5]), pick([2, 3, 4]) * 1e5], ['Server hardware delivery delayed', pick([0.05, 0.1, 0.2]), pick([6, 10, 12]) * 1e5]]; const RE = R.map(r => r[1] * r[2]); const top = RE.indexOf(Math.max(...RE)); const cost = pick([10, 20, 30, 50]) * 1000, newp = R[top][1] / 2; const rrl = (RE[top] - newp * R[top][2]) / cost;
      return { title: 'Risk register', topic: 't-risk', html: `<b class="k">Case: Risk register for an e-governance portal.</b> ${R.map((r, i) => `R${i + 1}: ${r[0]}, probability ${r[1]}, potential damage Rs. ${nf(r[2], 0)}.`).join(' ')} A mitigation for the highest-exposure risk costs Rs. ${nf(cost, 0)} and would halve its probability.`, qs: [
        nat({ g: 'p-re1', wk: 7, topic: 't-risk', v: RE[0], rel: 0, abs: 1, unit: 'Rs.', d: 0, text: 'Risk exposure of R1?', exp: `RE = ${R[0][1]} × ${nf(R[0][2], 0)} = <b>${nf(RE[0], 0)}</b>.` }),
        mcq({ g: 'p-rank', wk: 7, topic: 't-risk', text: 'Which risk has the highest exposure?', opts: ['R1', 'R2', 'R3'], ans: [top], exp: `RE: ${RE.map((x, i) => `R${i + 1} = ${nf(x, 0)}`).join(', ')}. Highest: <b>R${top + 1}</b>.` }),
        nat({ g: 'p-rrl', wk: 7, topic: 't-risk', v: rrl, rel: 0.01, d: 2, text: 'Risk reduction leverage of the proposed mitigation?', exp: `RRL = (RE<sub>before</sub> − RE<sub>after</sub>)/cost = (${nf(RE[top], 0)} − ${nf(newp * R[top][2], 0)})/${nf(cost, 0)} = <b>${nf(rrl)}</b> → ${rrl > 1 ? 'worth doing' : 'not worth doing'}.` }),
        mcq({ g: 'p-resp', wk: 7, topic: 't-risk', text: 'For R3 the team leases equipment locally as an interim arrangement. This response is…', opts: ['Mitigation (reduce impact)', 'Avoidance', 'Transfer', 'Acceptance'], ans: [0], exp: 'An interim arrangement that limits the damage while the risk still exists is mitigation (2019 assignment, week 7).' })] };
    },
    reliab: () => { const dem = pick([2000, 4000, 5000]), fail = rnd(2, 20); let t = 0; const ts = Array.from({ length: 5 }, () => (t += rnd(30, 150))); const mttf = (ts[4] - ts[0]) / 4, mttr = pick([2, 3, 4, 6]); const A = (mttf) / (mttf + mttr) * 100;
      return { title: 'Reliability log', topic: 't-reliab', html: `<b class="k">Case: Railway reservation server.</b> In the last test campaign the server failed at t = ${ts.join(', ')} hours of operation; each repair took ${mttr} hours on average. In a separate test, ${fail} of ${nf(dem, 0)} booking requests failed.`, qs: [
        nat({ g: 'p-mttf', wk: 12, topic: 't-reliab', v: mttf, rel: 0.004, unit: 'h', d: 2, text: 'MTTF from the failure times?', exp: `(${ts[4]} − ${ts[0]})/4 = <b>${nf(mttf)} h</b>.` }),
        nat({ g: 'p-mtbf', wk: 12, topic: 't-reliab', v: mttf + mttr, rel: 0.004, unit: 'h', d: 2, text: 'MTBF (= MTTF + MTTR)?', exp: `${nf(mttf)} + ${mttr} = <b>${nf(mttf + mttr)} h</b>.` }),
        nat({ g: 'p-av', wk: 12, topic: 't-reliab', v: (mttf + mttr) / (mttf + 2 * mttr) * 100, rel: 0, abs: 0.06, unit: '%', d: 2, text: 'Inherent availability = MTBF/(MTBF + MTTR), in %?', exp: `${nf(mttf + mttr)}/(${nf(mttf + mttr)} + ${mttr}) = <b>${nf((mttf + mttr) / (mttf + 2 * mttr) * 100)} %</b> (course formula A = MTBF/(MTBF + MTTR)).` }),
        nat({ g: 'p-pofod', wk: 12, topic: 't-reliab', v: fail / dem * 100, rel: 0.003, unit: '%', d: 3, text: 'POFOD in % for the booking requests?', exp: `${fail}/${dem} = <b>${nf(fail / dem * 100, 3)} %</b>.` }),
        mcq({ g: 'p-why', wk: 12, topic: 't-reliab', text: 'Why can two users of this server perceive different reliability?', opts: ['They exercise different features (different operational profiles)', 'Software wears out faster for heavy users', 'MTTF is observer-independent', 'Failures are always permanent'], ans: [0], exp: 'Reliability is observer-dependent: it depends on the operational profile.' })] };
    },
    compress: () => { const t1 = pick([12, 18, 24]), f = pick([0.5, 2 / 3, 0.75]), t2 = Math.round(t1 * f); const pu = (t1 / t2) ** 4, je = (t1 / t2) ** 2;
      return { title: 'Schedule compression', topic: 't-staffing', html: `<b class="k">Case: Tax-season deadline.</b> The nominal development time of a mid-sized product is ${t1} months. Marketing wants it in ${t2} months and offers to hire more developers.`, qs: [
        nat({ g: 'p-pu', wk: 5, topic: 't-staffing', v: pu, rel: 0.01, unit: 'times', d: 2, text: 'Effort increase factor by Putnam?', exp: `(${t1}/${t2})⁴ = <b>${nf(pu)}</b>.` }),
        nat({ g: 'p-je', wk: 5, topic: 't-staffing', v: je, rel: 0.01, unit: 'times', d: 2, text: 'Effort increase factor by Jensen?', exp: `(${t1}/${t2})² = <b>${nf(je)}</b>.` }),
        mcq({ g: 'p-feas', wk: 5, topic: 't-staffing', text: 'According to Boehm, is the compression feasible?', opts: f < 0.75 ? ['No: compressing below about 75 % of the nominal time is very unlikely to succeed', 'Yes: any compression is possible with enough staff', 'Yes, because Jensen predicts a small effort increase', 'No: no compression is ever possible'] : ['Borderline: 75 % of nominal is roughly the limit; more staff beyond this does not help', 'No: no compression is ever possible', 'Yes: any compression is possible with enough staff', 'Yes, because effort decreases when time is compressed'], ans: [0], exp: `Required = ${nf(f * 100, 0)} % of nominal. Boehm: the limit is about 75 % of the nominal estimate (limited parallel activities).` }),
        mcq({ g: 'p-brooks', wk: 5, topic: 't-staffing', type: 'msq', text: 'Why might adding developers late make the project later? (Select all that apply.)', opts: ['More communication paths', 'Newcomers must learn the system', 'Experienced members spend time training them', 'Limited scope for parallel work', 'Project scope automatically increases'], ans: [0, 1, 2, 3], exp: 'Brooks: communication overhead, learning, training effort and limited parallelism. Scope does not grow by itself (2026 assignment 5 Q9).' })] };
    },
    halstead: () => { const prog = pick([{ c: 'a = b + c;', ops: ['=', '+', ';'], opd: ['a', 'b', 'c'], N1: 3, N2: 3 }, { c: 'x = x * y + z;', ops: ['=', '*', '+', ';'], opd: ['x', 'y', 'z'], N1: 4, N2: 4 }, { c: 'if (a > b) max = a; else max = b;', ops: ['if…else', '()', '>', '=', ';'], opd: ['a', 'b', 'max'], N1: 7, N2: 6 }, { c: 'sum = sum + a[i]; i = i + 1;', ops: ['=', '+', '[]', ';'], opd: ['sum', 'a', 'i', '1'], N1: 7, N2: 7 }]); const n1 = prog.ops.length, n2 = prog.opd.length, N = prog.N1 + prog.N2, eta = n1 + n2, V = N * Math.log2(eta);
      return { title: 'Halstead metrics', topic: 't-halstead', html: `<b class="k">Snippet:</b> <code>${prog.c}</code><br>Using the lecture's counting rules (a statement terminator ';' is one operator, a parenthesis pair and if…else are single operators), the unique operators are ${prog.ops.map(o => `<code>${o}</code>`).join(' ')} (η₁ = ${n1}) and the unique operands are ${prog.opd.map(o => `<code>${o}</code>`).join(' ')} (η₂ = ${n2}). Total operators N₁ = ${prog.N1}, total operands N₂ = ${prog.N2}.`, qs: [
        nat({ g: 'p-N', wk: 5, topic: 't-halstead', v: N, rel: 0, abs: 0.01, d: 0, text: 'Program length N?', exp: `N = N₁ + N₂ = <b>${N}</b>.` }),
        nat({ g: 'p-eta', wk: 5, topic: 't-halstead', v: eta, rel: 0, abs: 0.01, d: 0, text: 'Vocabulary η?', exp: `η = η₁ + η₂ = <b>${eta}</b>.` }),
        nat({ g: 'p-V', wk: 5, topic: 't-halstead', v: V, rel: 0.006, unit: 'bits', d: 2, text: 'Volume V = N log₂ η?', exp: `${N} × log₂${eta} = <b>${nf(V)}</b>.` }),
        mcq({ g: 'p-E', wk: 5, topic: 't-halstead', text: 'How does Halstead effort E depend on V?', opts: ['E = V²/V*, i.e. it varies as the square of V', 'E = V × L', 'E = V/18', 'E is independent of V'], ans: [0], exp: 'E = V/L with L = V*/V ⇒ E = V²/V*. Time T = E/S, S = 18.' })] };
    },
    // ---- theory case studies (fixed text, randomised option order)
    caseStartup: () => ({ title: 'Case: outsourcing start-up', topic: 't-org', html: `<b class="k">Case.</b> Nimbus Soft is a 40-person start-up in Pune doing outsourced customization and maintenance projects for overseas clients. Each new contract gets its own team, which is dissolved when the contract ends. Requirements change every few weeks, the teams are small (5-8) and clients want frequent demos. Management wants a process certification that customers will recognise, at minimum cost.`, qs: [
      mcq({ g: 'c-org', wk: 7, topic: 't-org', text: 'Which organisation structure does Nimbus use?', opts: ['Project (projectized) organisation', 'Functional organisation', 'Strong matrix', 'Weak matrix'], ans: [0], exp: 'A team formed per project and dissolved at its end = project organisation (2019 assignment W7 Q9).' }),
      mcq({ g: 'c-sdlc', wk: 2, topic: 't-agile', text: 'Most suitable life cycle model?', opts: ['Agile (e.g. Scrum/XP)', 'Classical waterfall', 'V-model', 'Spiral with full risk analysis per loop'], ans: [0], exp: 'Small teams, frequently changing requirements, service-type (customization/maintenance) work and frequent demos → agile.' }),
      mcq({ g: 'c-cmm', wk: 11, topic: 't-cmm', text: 'Which SEI CMM level should it aim for first?', opts: ['Level 2 (Repeatable)', 'Level 4 (Managed)', 'Level 5 (Optimizing)', 'Level 1 (Initial)'], ans: [0], exp: 'A small outsourcing/maintenance company first needs basic project management (cost, schedule tracking, CM): level 2 (2019 W11 Q9).' }),
      mcq({ g: 'c-iso', wk: 11, topic: 't-iso', text: 'Which ISO standard applies to it?', opts: ['ISO 9001', 'ISO 9002', 'ISO 9003', 'ISO 9000-3 certification'], ans: [0], exp: 'ISO 9001 covers design, development, production and servicing, i.e. software development. ISO 9000-3 is only guidance for applying 9001 to software.' }),
      mcq({ g: 'c-contract', wk: 10, topic: 't-contract', text: 'Since requirements change every few weeks, which contract type suits the CLIENT best?', opts: ['Time and materials', 'Fixed price', 'Fixed price per delivered unit with frozen FP count', 'Open tendering'], ans: [0], exp: 'T&M makes changing requirements easy (customer pays per unit of effort); the customer carries the risk. Open tendering is a selection procedure, not a payment type.' })] }),
    caseAvionics: () => ({ title: 'Case: flight control software', topic: 't-waterfall', html: `<b class="k">Case.</b> AeroDyn is building flight-control software for a drone: 120 KLOC, hard real-time constraints, tight interfaces with new hardware, all requirements fixed by a certification authority, and the highest reliability requirement.`, qs: [
      mcq({ g: 'c-v', wk: 2, topic: 't-waterfall', text: 'Most suitable life cycle model?', opts: ['V-model', 'RAD', 'Build and fix', 'Scrum'], ans: [0], exp: 'V-model: natural choice for safety-critical, high-reliability systems with requirements known up front (test design in parallel with each phase).' }),
      mcq({ g: 'c-mode', wk: 5, topic: 't-cocomo', text: 'COCOMO 81 mode?', opts: ['Embedded', 'Organic', 'Semi-detached', 'Detached'], ans: [0], exp: 'New, innovative product with tight hardware/real-time constraints = embedded.' }),
      mcq({ g: 'c-rely', wk: 5, topic: 't-cocomo', text: 'In intermediate COCOMO, the very high reliability requirement will…', opts: ['scale the estimate upwards (RELY 1.40)', 'scale it downwards', 'leave it unchanged', 'only change the duration, not effort'], ans: [0], exp: 'Stringent reliability → RELY > 1 (very high 1.40) → effort scaled up (2026 A5 Q3).' }),
      mcq({ g: 'c-fp', wk: 4, topic: 't-fp', text: 'Best function point method for sizing it?', opts: ['COSMIC full function points', 'IFPUG function points', 'Mark II function points', 'Object points'], ans: [0], exp: 'COSMIC was designed for embedded/real-time software (entries, exits, reads, writes).' }),
      mcq({ g: 'c-team', wk: 7, topic: 't-org', text: 'Team structure for a project this large?', opts: ['Hierarchical (mixed) team', 'Chief programmer team', 'Democratic team', 'No structure: self-organising pairs'], ans: [0], exp: 'Large projects need a hierarchical structure (project leader → senior programmers → juniors); chief programmer and democratic teams suit small projects.' })] }),
    caseScrum: () => ({ title: 'Case: a Scrum team', topic: 't-agile', html: `<b class="k">Case.</b> A 7-member team builds a mobile wallet in month-long iterations. Riya decides which features matter most to customers and orders the list of all desired work. Arjun removes blockers and shields the team. Every morning the team meets standing for 15 minutes. Mid-iteration a sales head asks to add a new feature to the current iteration.`, qs: [
      mcq({ g: 's-po', wk: 2, topic: 't-agile', text: 'Riya\'s role is…', opts: ['Product owner', 'Scrum master', 'Chief programmer', 'Configuration librarian'], ans: [0], exp: 'The product owner represents the customer and prioritises the product backlog.' }),
      mcq({ g: 's-sm', wk: 2, topic: 't-agile', text: 'Arjun\'s role is…', opts: ['Scrum master', 'Product owner', 'Moderator', 'Programme manager'], ans: [0], exp: 'Scrum master: facilitates, removes impediments, buffers outside interference.' }),
      mcq({ g: 's-chg', wk: 2, topic: 't-agile', text: 'How should the mid-sprint feature request be handled?', opts: ['Add it to the product backlog for a later sprint', 'Add it to the current sprint backlog immediately', 'The scrum master implements it himself', 'Extend the sprint by two weeks'], ans: [0], exp: 'No changes are entertained during a sprint; new work goes to the product backlog and is prioritised by the PO.' }),
      mcq({ g: 's-q', wk: 2, topic: 't-agile', type: 'msq', text: 'Which questions are answered in the daily scrum? (Select all.)', opts: ['What did I do yesterday?', 'What will I do today?', 'What obstacles are in my way?', 'Who is behind schedule and why?', 'How do we fix the bug in the payment module?'], ans: [0, 1, 2], exp: 'Three questions only; not a problem-solving or blame session.' }),
      mcq({ g: 's-bd', wk: 2, topic: 't-agile', type: 'msq', text: 'A sprint burndown chart shows… (Select all.)', opts: ['Remaining effort (hours)', 'Progress across the sprint days', 'Work left until sprint completion', 'Customer satisfaction', 'Number of employees'], ans: [0, 1, 2], exp: 'Sprint burndown: remaining sprint-backlog hours per day, ideally reaching zero at the end (2026 A2 Q9).' })] }),
    caseConfig: () => ({ title: 'Case: version chaos', topic: 't-scm', html: `<b class="k">Case.</b> In a 12-person team two developers edited the same module and one overwrote the other's fix. Nobody could tell who changed the billing code last week or roll back to last month's release. The manager decides to put the SRS, design, code and test cases under a configuration management tool with reserve/restore operations and a change control board.`, qs: [
      mcq({ g: 'k-1', wk: 10, topic: 't-scm', text: 'Knowing who changed what and when is called…', opts: ['System accounting', 'Variant handling', 'Release management', 'Baselining'], ans: [0], exp: 'System accounting = who, what, when of each change.' }),
      mcq({ g: 'k-2', wk: 10, topic: 't-scm', text: 'The overwrite problem is solved because…', opts: ['Only one developer can reserve a module at a time until it is restored', 'The tool stores deltas', 'Variants are created for each developer', 'The CCB writes all code'], ans: [0], exp: 'Reserve/restore: a reserved item cannot be reserved by anyone else until restored (concurrent access problem).' }),
      mcq({ g: 'k-3', wk: 10, topic: 't-scm', text: 'Before a changed module is restored into the configuration…', opts: ['the change control board must approve it', 'the customer must sign it', 'it must be compiled to a binary for SCCS', 'all variants must be deleted'], ans: [0], exp: 'Restoring needs CCB approval (well-motivated, documented, tested, consistent with other changes).' }),
      mcq({ g: 'k-4', wk: 10, topic: 't-scm', text: 'A design note that will be put under configuration control after review is…', opts: ['Pre-controlled', 'Controlled', 'Uncontrolled', 'Post-controlled'], ans: [0], exp: 'Pre-controlled: not yet under configuration control but will be.' }),
      mcq({ g: 'k-5', wk: 10, topic: 't-scm', text: 'A Unix tool like SCCS stores versions MOD1.1, 1.2, 1.3 as…', opts: ['the original plus deltas (changes)', 'three complete copies', 'binary images', 'only the latest version'], ans: [0], exp: 'SCCS/RCS store the original and deltas to save disk space; they handle text files only.' })] }),
    casePeople: () => ({ title: 'Case: team motivation', topic: 't-people', html: `<b class="k">Case.</b> After a pay rise and a new air-conditioned office, the testers of a team are still unmotivated. They test only small fragments, never see the full product, and do not hear back about whether their bug reports mattered. Meanwhile the project manager asks everyone to work 60-hour weeks.`, qs: [
      mcq({ g: 'm-1', wk: 7, topic: 't-people', text: 'Pay and office conditions did not motivate them. Herzberg calls these…', opts: ['Hygiene factors', 'Motivators', 'Self-actualisation needs', 'Expectancy'], ans: [0], exp: 'Hygiene factors only remove dissatisfaction; motivators (achievement, recognition, the work itself, promotion) increase satisfaction.' }),
      mcq({ g: 'm-2', wk: 7, topic: 't-people', type: 'msq', text: 'Which Oldham-Hackman characteristics are missing? (Select all.)', opts: ['Task identity (seeing a whole piece of work)', 'Feedback', 'Salary', 'Task complexity'], ans: [0, 1], exp: 'They never see the whole product (task identity) and hear nothing back (feedback). Salary and "task complexity" are not in the model.' }),
      mcq({ g: 'm-3', wk: 7, topic: 't-people', text: 'Making each tester own a complete feature end to end is called…', opts: ['Job enrichment / job redesign', 'Theory X control', 'Resource smoothing', 'Crashing'], ans: [0], exp: 'Job redesign: enlargement (more tasks) or enrichment (more responsibility, whole tasks).' }),
      mcq({ g: 'm-4', wk: 7, topic: 't-people', text: 'The 60-hour week…', opts: ['raises stress and health risk; good PM (realistic estimates, control) should avoid it', 'is recommended by XP', 'is a Herzberg motivator', 'reduces role ambiguity'], ans: [0], exp: 'XP recommends a 40-hour week; studies linked >48 h/week to heart-disease risk. Good PM reduces stress via realistic estimates, fewer crises, clear roles.' })] }),
    caseClose: () => ({ title: 'Case: winding up a project', topic: 't-closeout', html: `<b class="k">Case.</b> A government portal project has delivered all features. The team is already being pulled into new projects, nobody wants to write the archive documents, and a senior developer who knows the deployment scripts is leaving next month. The sponsor is a separate external department.`, qs: [
      mcq({ g: 'x-1', wk: 10, topic: 't-closeout', type: 'msq', text: 'Which reasons for poor closure are visible here? (Select all.)', opts: ['Lack of interest of the project team', 'Underestimating how fast know-how is lost', 'A well-defined closure process', 'Excessive customer interest'], ans: [0, 1], exp: 'Team losing interest and knowledge loss risk. A defined closure process is a remedy, not a cause.' }),
      mcq({ g: 'x-2', wk: 10, topic: 't-closeout', text: 'Because the client is an external department, acceptance must be…', opts: ['formal: acceptance testing and written acceptance', 'informal, conveyed in meetings', 'skipped for government projects', 'given by the project manager'], ans: [0], exp: 'External client → formal acceptance testing and written sign-off; sister departments can accept informally.' }),
      mcq({ g: 'x-3', wk: 10, topic: 't-closeout', text: 'The LAST step of the close-out process is…', opts: ['Releasing staff', 'Getting client acceptance', 'Archiving deliverables', 'Financial closure'], ans: [0], exp: 'Steps: client acceptance → archive → preserve know-how → financial closure → post-implementation review → review report → release staff.' }),
      mcq({ g: 'x-4', wk: 10, topic: 't-closeout', text: 'The post-implementation review report should…', opts: ['include lessons learned and recommendations for similar projects', 'only list the bugs', 'assign blame for overruns', 'contain no recommendations'], ans: [0], exp: 'Project description, what worked, what impeded, prescription for other projects.' })] }),
  };
  const pnames = Object.keys(P);
  function passage(name) { const f = P[name]; if (!f) return null; const p = f(); p.name = name; p.qs.forEach((q, i) => { q.passage = i === 0 ? p.html : null; q.pass = name; q.passTitle = p.title; q.passHtml = p.html; }); return p; }
  return { make, names, passage, pnames, G, P, cpm, network, netTable, netWork };
})();
